SELECT /*selectExportExIvExportCiProcList*/ PODT.BUYER, (SELECT COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = PODT.BUYER) AS BUYER_NAME, POHD.PO_CREATE_DATE, PODT.RD_DATE, PODT.PO_NO, PODT.PO_SEQ, PODT.BUYER_ITEM_NO, PODT.DESCRIPTION, PODT.SPECIFICATION, PODT.UNIT_MEASURE, PODT.MAKER_NAME , POHD.DELY_TO_LOCATION, DECODE(POHD.DELY_TO_LOCATION,'','1','0') AS DELY_TO_LOCATION_IMG, PRDT.ADD_USER_NAME, PRDT.ADD_USER_TEL, (SELECT COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = POHD.AGENT) AS AGENT_NAME, (SELECT TEL_NO FROM ICOMCMPY CM WHERE CM.COM_CODE = POHD.AGENT) AS AGENT_TEL_NO, PODT.LEGACY_PO_NO, IVDT.INV_NO, PODT.ITEM_AMT, POHD.AGENT AS AGENT, POHD.PO_REMARK, PODT.DELAY_REMARK, PODT.SCM_REMARK, IVDT.INVOICE_DATE AS INV_DATE, PODT.PROCESS_TYPE, IVDT.PKG_RS_DATE, IVDT.PKG_GR_DATE, IVDT.PKG_GR_QTY, IVDT.PKG_GR_USER_ID, NVL(IVDT.PKG_CI_QTY,0) GI_PKG_CI_QTY, IVDT.PKG_GR_QTY - NVL(IVDT.PKG_CI_QTY,0) AS PKG_CI_QTY, (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = IVDT.PKG_GR_USER_ID) AS PKG_GR_USER_NM, IVDT.INV_QTY, IVDT.INV_SEQ, PRDT.EXP_CUR, PRDT.EXP_FOR_UNIT_PRICE ,POHD.PURCHASER_NAME AS PURCHASER_NAME ,COD2.TEXT1 AS PURCHASE_DEPT ,POHD.OVERSEA_TO_LOCATION ,PODT.PLANT ,PRDT.PURCHASER_DEPT AS PURCHASER_DEPT_CD FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMPRDT PRDT, ICOMIVDT IVDT, ICOMCOD2 COD2 WHERE PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND IVDT.STATUS <> 'D' AND PODT.PROCESS_TYPE = '0' AND NVL(IVDT.PKG_GR_QTY,0) > 0 AND POHD.PKG_COMPANY_CODE =#{st_pkg_cmpy_no} AND NVL(IVDT.PKG_CI_QTY,0)< NVL(IVDT.PKG_GR_QTY,0) AND PRDT.EXP_CUR IS NOT NULL AND PRDT.BUYER = COD2.COMPANY_CODE(+) AND COD2.TYPE(+) = 'C001' AND PRDT.PURCHASER_DEPT = COD2.CODE(+)
AND PODT.BUYER IN
#{item}
AND POHD.AGENT = #{st_agent_code}
AND IVDT.INV_NO LIKE #{st_inv_no}||'%'
AND PODT.PO_NO LIKE #{st_po_no}||'%'
AND PODT.LEGACY_PO_NO LIKE #{st_legacy_po_no}||'%'
AND IVDT.INV_NO LIKE #{st_inv_no}||'%'
AND UPPER(COD2.TEXT1) LIKE UPPER('%'||#{st_purchase_dept}||'%')
AND POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND IVDT.PKG_GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
UNION ALL SELECT PODT.BUYER, (SELECT COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = PODT.BUYER) AS BUYER_NAME, POHD.PO_CREATE_DATE, PODT.RD_DATE, PODT.PO_NO, PODT.PO_SEQ, PODT.BUYER_ITEM_NO, PODT.DESCRIPTION, PODT.SPECIFICATION, PODT.UNIT_MEASURE, PODT.MAKER_NAME , POHD.DELY_TO_LOCATION, DECODE(POHD.DELY_TO_LOCATION,'','1','0') AS DELY_TO_LOCATION_IMG, PRDT.ADD_USER_NAME, PRDT.ADD_USER_TEL, (SELECT COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = POHD.AGENT) AS AGENT_NAME, (SELECT TEL_NO FROM ICOMCMPY CM WHERE CM.COM_CODE = POHD.AGENT) AS AGENT_TEL_NO, PODT.LEGACY_PO_NO, IVDT.INV_NO, PODT.ITEM_AMT, POHD.AGENT AS AGENT, POHD.PO_REMARK, PODT.DELAY_REMARK, PODT.SCM_REMARK, IVDT.INV_DATE AS INV_DATE, PODT.PROCESS_TYPE, IVDT.PKG_RS_DATE, IVDT.PKG_GR_DATE, IVDT.PKG_GR_QTY, IVDT.PKG_GR_USER_ID, NVL(IVDT.PKG_CI_QTY,0) GI_PKG_CI_QTY, IVDT.PKG_GR_QTY - NVL(IVDT.PKG_CI_QTY,0) AS PKG_CI_QTY, (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = IVDT.PKG_GR_USER_ID) AS PKG_GR_USER_NM, IVDT.INV_QTY, IVDT.INV_SEQ, PRDT.EXP_CUR, PRDT.EXP_FOR_UNIT_PRICE ,POHD.PURCHASER_NAME AS PURCHASER_NAME ,COD2.TEXT1 AS PURCHASE_DEPT ,POHD.OVERSEA_TO_LOCATION ,PODT.PLANT ,PRDT.PURCHASER_DEPT AS PURCHASER_DEPT_CD FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMPRDT PRDT, WMSIVDT IVDT, ICOMCOD2 COD2 WHERE PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND IVDT.STATUS <> 'D' AND PODT.PROCESS_TYPE != '0' AND NVL(IVDT.PKG_GR_QTY,0) > 0 AND POHD.PKG_COMPANY_CODE =#{st_pkg_cmpy_no} AND NVL(IVDT.PKG_CI_QTY,0)< NVL(IVDT.PKG_GR_QTY,0) AND PRDT.EXP_CUR IS NOT NULL AND PRDT.BUYER = COD2.COMPANY_CODE(+) AND COD2.TYPE(+) = 'C001' AND PRDT.PURCHASER_DEPT = COD2.CODE(+)
AND PODT.BUYER IN
#{item}
AND POHD.AGENT = #{st_agent_code}
AND PODT.PO_NO LIKE #{st_po_no}||'%'
AND PODT.LEGACY_PO_NO LIKE #{st_legacy_po_no}||'%'
AND IVDT.INV_NO LIKE #{st_inv_no}||'%'
AND UPPER(COD2.TEXT1) LIKE UPPER('%'||#{st_purchase_dept}||'%')
AND POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND IVDT.PKG_GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
ORDER BY BUYER_NAME, PO_NO, PO_SEQ

