UPDATE ICOMIVDT A
SET
	PKG_RS_DATE = #{SCHEDULED_DATE}
	, PKG_GR_QTY = A.INV_QTY
	, PKG_GR_USER_ID = #{st_user_id} 
	WHERE A.BUYER = #{BUYER}
	AND A.INV_NO = #{INV_NO}
	AND STATUS != 'D'

