/*selectExportExIvIcomCodPop*/ SELECT COD.CODE , COD.TEXT1 , COD.TEXT2 , COD.TEXT3 , COD.TEXT4 FROM ICOMCOD2 COD WHERE COD.TYPE = 'EP01' AND COD.FLAG = 'Y' AND COD.COMPANY_CODE =#{st_com_code}
AND COD.CODE LIKE #{st_code}||'%'
AND UPPER(COD.TEXT1) LIKE UPPER('%'||#{st_text}||'%')


/*selectExportExIvKepExpCheck*/
SELECT
   COUNT(INV_NO) INV_NO
FROM (
	SELECT INV_NO FROM ICOMIVDT A
	WHERE A.BUYER = #{BUYER}
	AND A.INV_NO = #{INV_NO}
	AND A.INV_SEQ = #{INV_SEQ}
	AND PKG_GR_QTY  < NVL(PKG_CI_QTY,0) + #{PKG_CI_QTY}
	UNION ALL
	SELECT INV_NO FROM WMSIVDT  A
	WHERE A.BUYER = #{BUYER}
	AND A.INV_NO = #{INV_NO}
	AND A.INV_SEQ = #{INV_SEQ}
	AND PKG_GR_QTY  < NVL(PKG_CI_QTY,0) + #{PKG_CI_QTY}
) A

