INSERT INTO KEP_EXP_CIDT(
	 PKG_COMPANY_CODE
	 , BUYER
	 , AGENT
	 , CI_NO
	 , CI_SEQ
	 , STATUS
	 , BUYER_ITEM_NO
	 , DESCRIPTION
	 , SPECIFICATION
	 , UNIT_MEASURE
	 , PO_NO
	 , PO_SEQ
	 , LEGACY_PO_NO
	 , LEGACY_PO_SEQ
	 , INV_NO
	 , INV_SEQ
	 , PROCESS_TYPE
	 , INV_QTY
	 , NET_WEIGHT
	 , GROSS_WEIGHT
	 , CBM
	 , CTN_NO_FROM
	 , CTN_NO_TO
	 , CURRENCY_CODE
	 , UNIT_PRICE
	 , ITEM_AMT
	 , ADD_DATE
	 , ADD_USER_ID
	 , CHANGE_DATE
	 , CHANGE_USER_ID
)
SELECT 
	  #{st_pkg_cmpy_no}
	, A.BUYER
	, 'KRKORE0001'
	, #{CI_NO}
	, TO_CHAR( #{CI_SEQ}, 'FM000000')
	, 'C'
	, A.BUYER_ITEM_NO
	, NVL(B.DESCRIPTION_ENG, A.DESCRIPTION) AS DESCRIPTION
	, A.SPECIFICATION
	, A.UNIT_MEASURE
	, A.PO_NO
	, A.PO_SEQ
	, A.LEGACY_PO_NO
	, A.LEGACY_PO_SEQ
	, #{INV_NO}
	, #{INV_SEQ}
	, #{PROCESS_TYPE}
	, #{PKG_CI_QTY}
	, #{N_WEIGHT}
	, #{G_WEIGHT}
	, #{CBM}
	, #{CTN_FROM}
	, #{CTN_TO}
	, #{EXP_CUR}
	, #{EXP_FOR_UNIT_PRICE}
	, #{EXP_FOR_UNIT_PRICE}* #{PKG_CI_QTY}
	, SYSDATE
	, #{st_user_id}
	, SYSDATE
	, #{st_user_id}
FROM ICOMPODT A, ICOMBYIT B
WHERE  A.BYIT_COMORG_CODE = B.BUYER
AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO
AND A.BUYER = #{BUYER}
AND A.PO_NO = #{PO_NO}
AND A.PO_SEQ = #{PO_SEQ}


