/*"updateExportExIvExportIcomivdt"*/
UPDATE ICOMIVDT A
SET
	PKG_CI_QTY = #{PKG_CI_QTY} + NVL(PKG_CI_QTY,0)
	WHERE A.BUYER = #{BUYER}
	AND A.INV_NO = #{INV_NO}
	AND A.INV_SEQ = #{INV_SEQ}
	AND A.STATUS != 'D'


/*"updateExportExIvExportWmsivdt"*/
UPDATE WMSIVDT A
SET
	PKG_CI_QTY = #{PKG_CI_QTY} + NVL(PKG_CI_QTY,0)
	WHERE A.BUYER = #{BUYER}
	AND A.INV_NO = #{INV_NO}
	AND A.INV_SEQ = #{INV_SEQ}
	AND A.STATUS != 'D'

